def controller(obs, memory) -> int:
    """
    Refined staged controller for the key+locked-door+ball task.

    Stages:
      1 - SEARCH_KEY: explore until a key is visible
      2 - GOTO_KEY: navigate to the key and PICKUP it
      4 - GOTO_DOOR: with key, navigate to the matching locked door and TOGGLE (unlock)
      6 - ENTER_ROOM: move through the door into the room/corridor
      7 - DROP_KEY: find any empty cell (floor/empty) and DROP the key there
      8 - PICK_BALL: navigate to the ball and PICKUP (only when not carrying the key)

    Robustness improvements based on testing:
      - Do not attempt FORWARD when a blocking object is directly in front.
      - When carrying key, actively search for any empty cell to drop (not necessarily adjacent to ball).
      - Avoid getting stuck by alternating preferred turn direction after repeated turns.
      - Rely on current observation (obs['image']) and obs['last_action'] (what was actually executed)
        rather than assuming our last returned action executed.
    """
    # Actions
    TURN_LEFT = 0
    TURN_RIGHT = 1
    FORWARD = 2
    PICKUP = 3
    DROP = 4
    TOGGLE = 5
    DONE = 6

    img = obs['image']
    AX, AY = 3, 6  # agent cell in view
    FX, FY = 3, 5  # cell directly in front

    # helpers
    def cell(x, y):
        if 0 <= x <= 6 and 0 <= y <= 6:
            return tuple(img[x][y])
        return (0, 0, 0)

    def obj_at(x, y):
        return cell(x, y)[0]

    def color_at(x, y):
        return cell(x, y)[1]

    def state_at(x, y):
        return cell(x, y)[2]

    def find_all(obj_type):
        res = []
        for x in range(7):
            for y in range(7):
                if obj_at(x, y) == obj_type:
                    res.append((x, y))
        return res

    # initialize memory
    if 'phase' not in memory:
        memory['phase'] = 1
        memory['key_color'] = None
        memory['dropped_key'] = False
        memory['turn_prefer'] = TURN_RIGHT
        memory['consec_turns'] = 0

    # update counters based on what was actually executed last step
    executed = obs.get('last_action', None)
    if executed in (TURN_LEFT, TURN_RIGHT):
        memory['consec_turns'] = memory.get('consec_turns', 0) + 1
    else:
        memory['consec_turns'] = 0

    # if we've been turning a lot, flip turning preference to try escaping cycles
    if memory.get('consec_turns', 0) >= 5:
        memory['turn_prefer'] = TURN_LEFT if memory.get('turn_prefer') == TURN_RIGHT else TURN_RIGHT
        memory['consec_turns'] = 0

    # perception
    keys = find_all(5)
    balls = find_all(6)
    doors = find_all(4)

    carried_obj = obj_at(AX, AY)      # 5 if carrying a key, 6 for ball, 1 for nothing
    carried_color = color_at(AX, AY)

    # auto-phase updates
    if carried_obj == 5:
        memory['key_color'] = carried_color
        if memory['phase'] < 4:
            memory['phase'] = 4

    # If we dropped recently (observed executed DROP), record it
    if executed == DROP:
        memory['dropped_key'] = True

    # If ball is directly in front and we are allowed to PICKUP (not carrying key), go pick
    if obj_at(FX, FY) == 6 and carried_obj != 5:
        memory['phase'] = 8

    # If we see any ball in view while still carrying key, we ought to drop key first
    if balls and carried_obj == 5:
        memory['phase'] = 7

    phase = memory['phase']

    # utility: forward allowed (walkable)
    def forward_allowed():
        o = obj_at(FX, FY)
        if o in (1, 3, 8):  # empty, floor, goal
            return True
        if o == 4:  # door
            return state_at(FX, FY) == 0  # open
        return False

    # choose a simple nearest function (manhattan in view)
    def nearest(coords):
        return min(coords, key=lambda p: abs(p[0]-AX) + abs(p[1]-AY))

    # steering: make target cell (tx,ty) become the front cell (3,5)
    # returns an action (TURN_LEFT, TURN_RIGHT, FORWARD) or None if target is already front
    def steer_make_front(tx, ty):
        if (tx, ty) == (FX, FY):
            return None
        # if target is in same column, try forward to bring it closer
        if tx == AX:
            if forward_allowed():
                return FORWARD
            # front blocked: prefer toggle if a door, else turn
            if obj_at(FX, FY) == 4:
                return TOGGLE
            return memory['turn_prefer']
        # else rotate toward target horizontally
        if tx < AX:
            return TURN_LEFT
        else:
            return TURN_RIGHT

    # safe_forward: don't attempt forward if something blocking (wall/key/ball/box/closed door)
    def safe_forward():
        if forward_allowed():
            return FORWARD
        # if door in front, try toggle (open/unlock)
        if obj_at(FX, FY) == 4:
            return TOGGLE
        # otherwise turn (preferred direction)
        return memory['turn_prefer']

    # PHASE BEHAVIOR

    # Phase 1: SEARCH_KEY - explore until we see a key
    if phase == 1:
        if keys:
            memory['phase'] = 2
            phase = 2
        else:
            # move forward when possible, otherwise turn
            if forward_allowed():
                return FORWARD
            return memory['turn_prefer']

    # Phase 2: GOTO_KEY - navigate to key and PICKUP
    if phase == 2:
        if carried_obj == 5:
            memory['phase'] = 4
            return memory['turn_prefer']
        if not keys:
            memory['phase'] = 1
            return memory['turn_prefer']
        kx, ky = nearest(keys)
        if (kx, ky) == (FX, FY):
            return PICKUP
        act = steer_make_front(kx, ky)
        if act is None:
            # fallback
            return safe_forward()
        return act

    # Phase 4: GOTO_DOOR - with key, find the matching locked door and TOGGLE
    if phase == 4:
        if carried_obj != 5:
            # lost key, search again
            memory['phase'] = 1
            return memory['turn_prefer']
        keycol = memory.get('key_color', carried_color)
        locked_doors = [(dx, dy) for (dx, dy) in doors if state_at(dx, dy) == 2 and color_at(dx, dy) == keycol]
        if not locked_doors:
            # no locked door visible: explore corridor until we find it
            return safe_forward()
        dx, dy = nearest(locked_doors)
        if (dx, dy) == (FX, FY):
            # attempt to unlock
            return TOGGLE
        act = steer_make_front(dx, dy)
        if act is None:
            return safe_forward()
        return act

    # After unlocking the door, we will enter (phase 6). We may directly observe open door -> move forward.
    if phase == 6:
        # If front is open door or walkable, go forward
        if forward_allowed():
            return FORWARD
        # If front is a door closed but unlocked, toggle to open
        if obj_at(FX, FY) == 4:
            return TOGGLE
        # else explore
        return memory['turn_prefer']

    # If we just unlocked (we might still be in phase 4), detect open door in view and switch to ENTER_ROOM
    if phase == 4:
        if any(obj_at(dx, dy) == 4 and state_at(dx, dy) == 0 for (dx, dy) in doors):
            memory['phase'] = 6
            phase = 6

    # Phase 7: DROP_KEY - find any empty cell and drop the key there before picking the ball
    if phase == 7:
        # If we no longer carry the key, we dropped it -> go to pick ball
        if carried_obj != 5:
            memory['dropped_key'] = True
            memory['phase'] = 8
            return memory['turn_prefer']
        # Prefer to drop on front if it's an empty/floor cell
        if obj_at(FX, FY) in (1, 3):  # treat both empty (1) and floor (3) as acceptable drop spots
            return DROP
        # Otherwise search for any empty/floor cell in view
        empties = []
        for x in range(7):
            for y in range(7):
                if obj_at(x, y) in (1, 3):
                    empties.append((x, y))
        if empties:
            tx, ty = nearest(empties)
            act = steer_make_front(tx, ty)
            if act is None:
                return DROP
            return act
        # If we don't see empty cells, try to move around to discover one
        if forward_allowed():
            return FORWARD
        return memory['turn_prefer']

    # Phase 8: PICK_BALL - navigate to and pick the ball (only when not carrying key)
    if phase == 8:
        if carried_obj == 5:
            # somehow regained key; go back to dropping it
            memory['phase'] = 7
            return memory['turn_prefer']
        # If ball immediately in front -> pick up
        if obj_at(FX, FY) == 6:
            return PICKUP
        # If balls visible, steer towards nearest one
        if balls:
            bx, by = nearest(balls)
            act = steer_make_front(bx, by)
            if act is None:
                return FORWARD if forward_allowed() else memory['turn_prefer']
            return act
        # If no ball visible, explore
        if forward_allowed():
            return FORWARD
        return memory['turn_prefer']

    # Default fallback: try to progress safely
    if forward_allowed():
        return FORWARD
    return memory['turn_prefer']
