def controller(obs, memory) -> int:
    """
    Controller for the key+locked-door+ball task with improved exploration and door handling.

    Main behaviours (phases):
      1 - SEARCH_KEY: systematically explore corridor and open closed (unlocked) doors
      2 - GOTO_KEY: go to a visible key and PICKUP
      4 - GOTO_DOOR: carrying key, find matching locked door and TOGGLE (unlock)
      6 - ENTER_ROOM: move through open door
      7 - DROP_KEY: drop key on any empty/floor cell (prefer adjacent to ball if visible)
      8 - PICK_BALL: go to and PICKUP the ball (when not carrying key)

    Improvements made from testing traces:
      - When not carrying a key, proactively open closed (unlocked) doors (state == 1) by steering to them and TOGGLE.
      - When encountering a wall directly in front repeatedly, perform a deterministic two-turn escape (TURN_RIGHT twice) to face back and then move.
      - When no door is found for several steps while carrying the key, force an aggressive exploration pattern to escape local loops.
      - Record what action actually executed (obs['last_action']) and detect whether FORWARD moved the agent, to avoid repeated useless FORWARDs.
    """
    # Actions
    TURN_LEFT = 0
    TURN_RIGHT = 1
    FORWARD = 2
    PICKUP = 3
    DROP = 4
    TOGGLE = 5
    DONE = 6

    img = obs['image']
    AX, AY = 3, 6  # agent cell coordinates in view
    FX, FY = 3, 5  # front cell coordinates in view

    # Helpers to read view
    def cell(x, y):
        if 0 <= x <= 6 and 0 <= y <= 6:
            return tuple(img[x][y])
        return (0, 0, 0)

    def obj_at(x, y):
        return cell(x, y)[0]

    def color_at(x, y):
        return cell(x, y)[1]

    def state_at(x, y):
        return cell(x, y)[2]

    def find_all(obj_type):
        res = []
        for x in range(7):
            for y in range(7):
                if obj_at(x, y) == obj_type:
                    res.append((x, y))
        return res

    # Initialize persistent memory
    if 'phase' not in memory:
        memory.update({
            'phase': 1,
            'key_color': None,
            'dropped_key': False,
            'turn_prefer': TURN_RIGHT,
            'consec_turns': 0,
            'consec_forward_fail': 0,
            'prev_front': None,
            'prev_center': None,
            'last_executed': None,
            'no_door_steps': 0,
            'aggr_step': 0,
            'wall_turns': 0,   # counts turning attempts when a wall is in front
        })

    # Record what actually executed last step
    executed = obs.get('last_action', None)
    memory['last_executed'] = executed

    # Detect if a FORWARD actually moved the agent by comparing previous front cell content to current center
    moved_forward = False
    if executed == FORWARD and memory.get('prev_front') is not None:
        if memory['prev_front'] == img[AX][AY]:
            moved_forward = True

    # Update rotation / forward failure counters
    if executed in (TURN_LEFT, TURN_RIGHT):
        memory['consec_turns'] = memory.get('consec_turns', 0) + 1
    else:
        memory['consec_turns'] = 0

    if executed == FORWARD:
        if moved_forward:
            memory['consec_forward_fail'] = 0
        else:
            memory['consec_forward_fail'] = memory.get('consec_forward_fail', 0) + 1
    else:
        # slowly decay forward_fail counter
        memory['consec_forward_fail'] = max(0, memory.get('consec_forward_fail', 0) - 1)

    # Perception
    keys = find_all(5)
    balls = find_all(6)
    doors = find_all(4)
    carried_obj = obj_at(AX, AY)  # 5 key, 6 ball, 1 nothing
    carried_color = color_at(AX, AY)

    # Automatic phase updates
    if carried_obj == 5:
        memory['key_color'] = carried_color
        if memory['phase'] < 4:
            memory['phase'] = 4

    if executed == DROP:
        memory['dropped_key'] = True

    # If ball visible and carrying key -> need to drop
    if balls and carried_obj == 5 and memory.get('phase', 0) < 7:
