```python
def controller(obs, memory) -> int:
    """
    Controller for the key + locked-door + ball task with safeguards to avoid repeated ineffective TOGGLEs.

    Fixes and improvements:
      - Compare view cells using the cell() helper (tuples) to avoid list/tuple mismatches.
      - Avoid repeatedly toggling the same door if toggles have had no visible effect.
      - Only attempt to toggle a locked door if carrying a key of the same color.
      - When toggling is discouraged, prefer moving forward (if possible) or turning to escape loops.
      - Various escape patterns when stuck or when carrying key but no door visible.
    """
    # Actions
    TURN_LEFT = 0
    TURN_RIGHT = 1
    FORWARD = 2
    PICKUP = 3
    DROP = 4
    TOGGLE = 5
    DONE = 6

    img = obs['image']
    AX, AY = 3, 6  # agent center in view (tuple coordinates)
    FX, FY = 3, 5  # front cell coordinates

    # helpers to read view consistently as tuples
    def cell(x, y):
        if 0 <= x <= 6 and 0 <= y <= 6:
            return tuple(img[x][y])
        return (0, 0, 0)

    def obj_at(x, y):
        return cell(x, y)[0]

    def color_at(x, y):
        return cell(x, y)[1]

    def state_at(x, y):
        return cell(x, y)[2]

    def find_all(obj_type):
        res = []
        for x in range(7):
            for y in range(7):
                if obj_at(x, y) == obj_type:
                    res.append((x, y))
        return res

    # initialize memory defaults
    if 'phase' not in memory:
        memory.update({
            'phase': 1,
            'key_color': None,
            'dropped_key': False,
            'turn_prefer': TURN_RIGHT,
            'consec_turns': 0,
            'consec_forward_fail': 0,
            'prev_front': None,       # previous front cell content (tuple)
            'prev_center': None,      # previous center cell content (tuple)
            'last_executed': None,
            'no_door_steps': 0,
            'aggr_step': 0,
            'wall_mode_step': 0,
            'recent_toggles': 0,      # decayed counter of recent ineffective toggles
            'stuck_steps': 0,
            'last_toggle_front': None, # which front cell we last toggled (tuple)
            'toggle_repeat': 0,       # how many times we toggled the same front without visible change
        })

    # record what actually executed last step
    executed = obs.get('last_action', None)
    memory['last_executed'] = executed

    # detect whether a FORWARD actually moved the agent by comparing stored prev_front tuple to current center tuple
    moved_forward = False
    if executed == FORWARD and memory.get('prev_front') is not None:
        if memory['prev_front'] == cell(AX, AY):
            moved_forward = True

    # update counters based on executed
    if executed in (TURN_LEFT, TURN_RIGHT):
        memory['consec_turns'] = memory.get('consec_turns', 0) + 1
        memory['stuck_steps'] = memory.get('stuck_steps', 0) + 1
    else:
        memory['consec_turns'] = 0

    if executed == FORWARD:
        if moved_forward:
            memory['consec_forward_fail'] = 0
            memory['stuck_steps'] = 0
        else:
            memory['consec_forward_fail'] = memory.get('consec_forward_fail', 0) + 1
            memory['stuck_steps'] = memory.get('stuck_steps', 0) + 1
    else:
        # slowly decay forward failure counter
        memory['consec_forward_fail'] = max(0, memory.get('consec_forward_fail', 0) - 1)

    # Handle executed TOGGLE: update last_toggle_front / toggle_repeat based on whether view changed
    if executed == TOGGLE:
        # prev_front is the cell we attempted to toggle (tuple)
        prev_front = memory.get('prev_front')
        curr_front = cell(FX, FY)
        # If we toggled the same front as last_toggle_front and front didn't visibly change, increment repeat
        if memory.get('last_toggle_front') is not None and memory.get('last_toggle_front') == prev_front and prev_front == curr_front:
            memory['toggle_repeat'] = memory.get('toggle_repeat', 0) + 1
        else:
            # reset or initialize
            memory['toggle_repeat'] = 0 if prev_front is None else 1
        memory['last_toggle_front'] = prev_front
        # update recent_toggles as a decaying indicator
        if prev_front == curr_front:
            memory['recent_toggles'] = memory.get('recent_toggles', 0) + 1
        else:
            memory['recent_toggles'] = 0
        # update stuck_steps if toggle had no visible effect
        if prev_front == curr_front:
            memory['stuck_steps'] = memory.get('stuck_steps', 0) + 1
        else:
            memory['stuck_steps'] = 0
    else:
        # decay recent_toggles gradually
        memory['recent_toggles'] = max(0, memory.get('recent_toggles', 0) - 1)
        # do not alter last_toggle_front/toggle_repeat here

    # perception
    keys = find_all(5)
    balls = find_all(6)
    doors = find_all(4)

    carried_obj = obj_at(AX, AY)  # 5 key, 6 ball, 1 nothing
    carried_color = color_at(AX, AY)

    # auto-phase updates
    if carried_obj == 5:
        memory['key_color'] = carried_color
        if memory['phase'] < 4:
            memory['phase'] = 4

    if executed == DROP:
        memory['dropped_key'] = True

    # transition heuristics
    if balls and carried_obj == 5 and memory.get('phase', 0) < 7:
        memory['phase'] = 7

    if obj_at(FX, FY) == 6 and carried_obj != 5 and memory.get('dropped_key', False):
        memory['phase'] = 8

    # utilities
    def forward_allowed():
        o = obj_at(FX, FY)
        if o in (1, 3, 8):  # empty, floor, goal
            return True
        if o == 4:  # door
            return state_at(FX, FY) == 0  # open door
        return False

    def nearest(coords):
        return min(coords, key=lambda p: abs(p[0] - AX) + abs(p[1] - AY))

    # Decide whether toggling front door is sensible. Returns True if we should TOGGLE now.
    def should_toggle_front():
        if obj_at(FX, FY) != 4:
            return False
        st = state_at(FX, FY)
        door_color = color_at(FX, FY)
        # If door is locked (2), only toggle if carrying matching key
        if st == 2:
            if carried_obj == 5 and memory.get('key_color') == door_color:
                # allow a toggle, but avoid repeating on same front if it had no visible effect
                last_front = memory.get('last_toggle_front')
                prev_front = memory.get('prev_front')
                if last_front is not None and last_front == prev_front and memory.get('toggle_repeat', 0) >= 1:
                    return False
                return True
            else:
                return False
        # If door is closed (1), toggling should open it; allow one toggle unless repeated ineffective toggles observed
        if st == 1:
            last_front = memory.get('last_toggle_front')
            prev_front = memory.get('prev_front')
            if last_front is not None and last_front == prev_front and memory.get('toggle_repeat', 0) >= 1:
                return False
            return True
        # If door is open (0), no need to toggle
        return False

    # Steering to make (tx,ty) become the front cell (FX,FY)
    def steer_make_front(tx, ty):
        if (tx, ty) == (FX, FY):
            return None
        if tx == AX:
            if forward_allowed():
                return FORWARD
            # if front is a door, prefer toggling only when useful
            if obj_at(FX, FY) == 4:
                return TOGGLE if should_toggle_front() else memory['turn_prefer']
            return memory['turn_prefer']
        if tx < AX:
            return TURN_LEFT
        return TURN_RIGHT

    # safe forward: prefer forward if allowed, but avoid repeated useless forwards; handle front door carefully
    def safe_forward():
        if forward_allowed():
            if memory.get('consec_forward_fail', 0) >= 2:
                # try turning to find another path
                memory['turn_prefer'] = TURN_LEFT if memory.get('turn_prefer') == TURN_RIGHT else TURN_RIGHT
                memory['consec_turns'] += 1
                return memory['turn_prefer']
            return FORWARD
        # if front is a door, toggle only if it's useful
        if obj_at(FX, FY) == 4:
            if should_toggle_front():
                return TOGGLE
            # otherwise, try turning to find other approach
            return memory['turn_prefer']
        # else turn preferred direction
        if memory.get('consec_turns', 0) >= 4:
            memory['turn_prefer'] = TURN_LEFT if memory.get('turn_prefer') == TURN_RIGHT else TURN_RIGHT
            memory['consec_turns'] = 0
        return memory['turn_prefer']

    # helper: record prev_front/prev_center and return action
    def record_and_return(a):
        memory['prev_front'] = cell(FX, FY)
        memory['prev_center'] = cell(AX, AY)
        memory['aggr_step'] = (memory.get('aggr_step', 0) + 1) % 1000
        return a

    # Quick escape when wall in front: deterministic small sequence to avoid spinning toggles
    if obj_at(FX, FY) == 2:
        wm = memory.get('wall_mode_step', 0)
        if wm == 0:
            memory['wall_mode_step'] = 1
            memory['stuck_steps'] = memory.get('stuck_steps', 0) + 1
            return record_and_return(TURN_RIGHT)
        elif wm == 1:
            memory['wall_mode_step'] = 2
            memory['stuck_steps'] = memory.get('stuck_steps', 0) + 1
            if forward_allowed():
                return record_and_return(FORWARD)
            return record_and_return(TURN_LEFT)
        else:
            memory['wall_mode_step'] = 0
            if forward_allowed():
                return record_and_return(FORWARD)
            memory['stuck_steps'] = memory.get('stuck_steps', 0) + 1
            return record_and_return(TURN_RIGHT)
    else:
        memory['wall_mode_step'] = 0

    phase = memory['phase']

    # Phase 1: SEARCH_KEY
    if phase == 1:
